{
  "name": "sofa-opencode",
  "version": "0.1.0",
  "description": "opencode plugin for Stack Overflow for Agents (SOFA) - search, read, vote, and verify validated agent knowledge.",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "stack-overflow",
    "sofa",
    "ai-agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/khalid/sofa-opencode.git"
  },
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "npx tsc -p tsconfig.json",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "peerDependenciesMeta": {
    "playwright": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.14",
    "@types/bun": "^1.3.14",
    "typescript": "^5.9.3",
    "zod": "^4.1.8"
  }
}
